#!/usr/bin/env python3
"""Write docs/routing-status.md: what is still unrouted on each board, from KiCad's DRC.  Run from anywhere."""
import collections
import json
import os
import re
import subprocess
import tempfile

HW = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
BOARDS = [('carrier', 'Carrier'), ('keyboard', 'Keyboard (Alps)'), ('keyboard-topplate', 'Top plate'),
          ('keyboard-flex', 'Keyboard flex cable'), ('keyboard-5135', 'Keyboard (Keystone dome variant)')]
out = ['# Routing status', '',
       'Generated by `hardware/scripts/routing_status.py` from `kicad-cli pcb drc`. "Unrouted" is KiCad\'s count of',
       'unconnected items; "errors" are DRC errors (warnings such as silkscreen overlaps are not listed).', '']
for d, title in BOARDS:
    f = tempfile.mktemp(suffix='.json')
    subprocess.run(['kicad-cli', 'pcb', 'drc', '--schematic-parity', '--format', 'json', '-o', f,
                    os.path.join(HW, d, d + '.kicad_pcb')], stdout=subprocess.DEVNULL, check=True)
    j = json.load(open(f)); os.remove(f)
    errs = [v for v in j['violations'] if v['severity'] == 'error']
    nets = collections.Counter()
    rows = []
    for u in j['unconnected_items']:
        a, b = u['items'][0], u['items'][1]
        m = re.search(r'\[(.*?)\]', a['description'])
        net = m.group(1) if m else '?'
        nets[net] += 1
        rows.append((net, a['description'].split(' on ')[0], b['description'].split(' on ')[0],
                     '%.1f, %.1f' % (a['pos']['x'], a['pos']['y'])))
    out += [f'## {title} (`hardware/{d}`)', '',
            f'Unrouted: **{len(rows)}**. DRC errors: **{len(errs)}**. Schematic parity issues: **{len(j["schematic_parity"])}**.', '']
    if rows:
        out += ['| Net | From | To | Near (mm) |', '|---|---|---|---|']
        out += [f'| {n} | {a} | {b} | {p} |' for n, a, b, p in sorted(rows)]
        out.append('')
open(os.path.join(HW, '..', 'docs', 'routing-status.md'), 'w').write('\n'.join(out) + '\n')
print('\n'.join(l for l in out if l.startswith('## ') or l.startswith('Unrouted')))
